mapper.update:
UPDATE job_goal_qualification
SET del_yn = 'Y',
    modified_date = NOW(),
    modified_nm = #{modifiedNm}
WHERE goal_id = #{goalId}
  AND del_yn = 'N'

UPDATE job_goal_course
SET del_yn = 'Y',
    modified_date = NOW(),
    modified_nm = #{modifiedNm}
WHERE goal_id = #{goalId}
  AND del_yn = 'N'

UPDATE job_goal_training
SET del_yn = 'Y',
    modified_date = NOW(),
    modified_nm = #{modifiedNm}
WHERE goal_id = #{goalId}
  AND del_yn = 'N'

mapper.insert:
INSERT INTO job_goal_course (goal_id, course_id, selected_cost, created_date, created_nm, del_yn) SELECT #{goalId}, c.course_id, COALESCE(c.military_price, c.discount_price, c.original_price, 0), NOW(), #{createdNm}, 'N' FROM job_course c WHERE c.course_id IN
#{courseId}
AND c.del_yn = 'N' ON DUPLICATE KEY UPDATE selected_cost = VALUES(selected_cost), modified_date = NOW(), modified_nm = VALUES(created_nm), del_yn = 'N'

mapper.update:
UPDATE job_goal
SET status = #{status},
    modified_date = NOW(),
    modified_nm = #{modifiedNm}
WHERE goal_id = #{goalId}
  AND del_yn = 'N'
